def compute(vars):
    total_goodwill = vars["v1"]
    agiletics_goodwill = vars["v2"]

    if total_goodwill == 0:
        return None

    ratio = agiletics_goodwill / total_goodwill
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "total_goodwill_acquired": total_goodwill,
            "agiletics_goodwill_acquired": agiletics_goodwill,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
